import{useEffect,useState}from"react";import{getVendorAnalytics,getMyListings}from"../../api/vendorApi";export default function Analytics(){const[a,setA]=useState({}),[p,setP]=useState([]);useEffect(()=>{getVendorAnalytics().then(r=>setA(r.data?.data||{})).catch(()=>{});getMyListings().then(r=>setP(r.data?.data||[])).catch(()=>{})},[]);const views=p.reduce((n,x)=>n+(x.views||0),0);return <div className="mx-auto max-w-7xl px-4 py-8"><p className="text-sm text-slate-400">VENDOR</p><h1 className="text-3xl font-black">Analytics</h1><div className="mt-6 grid gap-4 sm:grid-cols-2 lg:grid-cols-4">{[["Listings",p.length],["Views",views],["Tracked events",a.events||0],["Enquiries",a.enquiries||0]].map(([k,v])=><div className="card p-5" key={k}><p className="text-sm text-slate-400">{k}</p><p className="mt-2 text-3xl font-black">{v}</p></div>)}</div><div className="card mt-6 p-6"><h2 className="font-bold">Top listings by views</h2>{[...p].sort((x,y)=>(y.views||0)-(x.views||0)).slice(0,10).map(x=><div className="flex justify-between border-b border-slate-100 py-3" key={x.id}><span>{x.title}</span><b>{x.views||0}</b></div>)}</div></div>}
